import{_ as e,o as d,c as s,ai as a}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"OpenBiz 实战（10 个独立商用应用）","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/index.md","filePath":"apps/openbiz/index.md"}'),i={name:"apps/openbiz/index.md"};function n(o,t,r,p,c,l){return d(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="openbiz-实战-10-个独立商用应用" tabindex="-1">OpenBiz 实战（10 个独立商用应用） <a class="header-anchor" href="#openbiz-实战-10-个独立商用应用" aria-label="Permalink to “OpenBiz 实战（10 个独立商用应用）”">​</a></h1><blockquote><p>一句话结论：<strong>OpenBiz 可作为 A 类（企业 / 工业 / 办公）商用系统的统一底座，且已按「一个应用 = 独立后端 + 独立前端 + 独立数据库 + 独立 git 仓库」的交付形态落地 10 个完整应用</strong>，每个都是可独立运行、独立演示的商用系统。全部真实跑通 MySQL，前后端经 Vite 代理全链路联调通过。</p></blockquote><h2 id="架构演进" tabindex="-1">架构演进 <a class="header-anchor" href="#架构演进" aria-label="Permalink to “架构演进”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>形态</th><th>状态</th></tr></thead><tbody><tr><td>试水期</td><td>8 个独立 Spring Boot consumer（端口 18081–18089，共享 ry-vue 库）</td><td>✅ 证明模式可复制</td></tr><tr><td>阶段二</td><td>合并为 1 个单体后端 + 1 个前端</td><td>⛔ 已废弃（偏离「100 套独立应用」目标，合并版已删除）</td></tr><tr><td><strong>当前</strong></td><td><strong>10 个独立应用</strong>：各自 backend（Spring Boot）+ frontend（Vue3/TS）+ 独立数据库 + 独立 git 仓库</td><td>✅ 已联调验证</td></tr></tbody></table><h2 id="_10-个独立应用总览" tabindex="-1">10 个独立应用总览 <a class="header-anchor" href="#_10-个独立应用总览" aria-label="Permalink to “10 个独立应用总览”">​</a></h2><p>统一命名 <code>E:/8.cangku/for-job/openbiz-{名称}-app/</code>，每个应用一套四件套：</p><table tabindex="0"><thead><tr><th>#</th><th>应用</th><th>目录</th><th>后端端口</th><th>独立数据库</th><th>表数</th><th>端点</th><th>关键状态机</th><th>实证页</th></tr></thead><tbody><tr><td>1</td><td>工单系统</td><td><code>openbiz-workorder-app</code></td><td>18081</td><td><code>openbiz_workorder</code></td><td>1</td><td>15</td><td>CREATED→ASSIGNED→ACCEPTED→COMPLETED</td><td><a href="/my-vitepress-site/apps/openbiz/workorder.html">工单</a></td></tr><tr><td>2</td><td>MES 生产执行</td><td><code>openbiz-mes-app</code></td><td>18082</td><td><code>openbiz_mes</code></td><td>13</td><td>36</td><td>CREATED→STARTED→REPORTED→QC_PASSED→COMPLETED</td><td><a href="/my-vitepress-site/apps/openbiz/mes.html">MES</a></td></tr><tr><td>3</td><td>项目管理系统</td><td><code>openbiz-pms-app</code></td><td>18083</td><td><code>openbiz_pms</code></td><td>2</td><td>28</td><td>项目 + 任务双状态机</td><td><a href="/my-vitepress-site/apps/openbiz/pms.html">PMS</a></td></tr><tr><td>4</td><td>CRM 客户关系</td><td><code>openbiz-crm-app</code></td><td>18084</td><td><code>openbiz_crm</code></td><td>2</td><td>25</td><td>客户 NEW→ACTIVE→CHURNED；商机 DRAFT→NEGOTIATING→WON/LOST</td><td><a href="/my-vitepress-site/apps/openbiz/crm.html">CRM</a></td></tr><tr><td>5</td><td>ERP 企业资源</td><td><code>openbiz-erp-app</code></td><td>18085</td><td><code>openbiz_erp</code></td><td>7</td><td>41</td><td>采购单 DRAFT→SUBMITTED→APPROVED→ORDERED→RECEIVED</td><td><a href="/my-vitepress-site/apps/openbiz/erp.html">ERP</a></td></tr><tr><td>6</td><td>WMS 仓储管理</td><td><code>openbiz-wms-app</code></td><td>18086</td><td><code>openbiz_wms</code></td><td>17</td><td>70</td><td>入库/出库/调拨/盘点单据链 + 批次效期</td><td><a href="/my-vitepress-site/instances/industrial/wms.html">WMS</a></td></tr><tr><td>7</td><td>OA 办公自动化</td><td><code>openbiz-oa-app</code></td><td>18087</td><td><code>openbiz_oa</code></td><td>2</td><td>17</td><td>请假单 + 公告双状态机</td><td><a href="/my-vitepress-site/apps/openbiz/oa.html">OA</a></td></tr><tr><td>8</td><td>BPM 流程管理</td><td><code>openbiz-bpm-app</code></td><td>18088</td><td><code>openbiz_bpm</code></td><td>2</td><td>23</td><td>流程定义 + 实例双状态机</td><td><a href="/my-vitepress-site/apps/openbiz/bpm.html">BPM</a></td></tr><tr><td>9</td><td>IIoT 工业物联</td><td><code>openbiz-iiot-app</code></td><td>18089</td><td><code>openbiz_iiot</code></td><td>11</td><td>78</td><td>设备 + 告警双状态机</td><td><a href="/my-vitepress-site/apps/openbiz/iiot.html">IIoT</a></td></tr><tr><td>10</td><td>HRM 人力资源</td><td><code>openbiz-hrm-app</code></td><td>18091</td><td><code>openbiz_hrm</code></td><td>14</td><td>97</td><td>组织/岗位/员工/合同 + 班次排班考勤</td><td><a href="/my-vitepress-site/instances/office/hrm.html">HRM</a></td></tr></tbody></table><blockquote><p>端点数为后端 <code>@*Mapping</code> 注解的实际计数（<code>grep -rhoE &quot;@(Get|Post|Put|Delete)Mapping&quot;</code>）。 表数为该库中<strong>非 RuoYi 系统表</strong>（<code>sys_*</code> / <code>qrtz_*</code>）、非代码生成器表（<code>gen_*</code>）、非平台基础表（<code>openbiz_tenant</code> / <code>openbiz_member</code>）的实际张数。其中 ERP 为 6 张业务表 + 1 张单号计数器表（<code>openbiz_erp_order_seq</code>），其余应用均为纯业务表。</p></blockquote><p>每个应用目录结构：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openbiz-{名称}-app/</span></span>
<span class="line"><span>├── backend/    # 独立 Spring Boot（RuoYi 3.9.2 + openbiz-saas-core 多租户基座）</span></span>
<span class="line"><span>├── frontend/   # 独立 Vue3 + TS 前端（元数据驱动）</span></span>
<span class="line"><span>├── sql/        # 本系统业务表建表脚本</span></span>
<span class="line"><span>├── docs/       # 设计文档（数据模型 / 状态机 / 接口契约 / 验收记录）</span></span>
<span class="line"><span>└── README.md   # 运行方式 + E2E 证据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="数据库-一应用一库" tabindex="-1">数据库：一应用一库 <a class="header-anchor" href="#数据库-一应用一库" aria-label="Permalink to “数据库：一应用一库”">​</a></h2><p>10 个应用各自独立数据库（<code>openbiz_{名称}</code>），每库包含：</p><ol><li>RuoYi 系统表（<code>sys_*</code> + quartz，含 admin 账号）——登录/权限/定时任务</li><li>OpenBiz 平台基础表（<code>openbiz_tenant</code> / <code>openbiz_member</code>）——多租户基座</li><li><strong>仅本系统的业务表</strong>——干净结构，无其他系统数据</li></ol><p>业务表张数按复杂度递增：工单 1 张 → CRM/PMS/OA/BPM 2 张 → ERP 6 业务表（+1 计数器）→ IIoT 11 张 → MES 13 张 → HRM 14 张 → WMS 17 张。</p><p>各库账号体系互相独立（各有 admin / admin123），租户数据物理隔离——这是「独立交付」的应有形态。</p><h2 id="版本控制-10-个应用各自独立-git-仓库" tabindex="-1">版本控制：10 个应用各自独立 git 仓库 <a class="header-anchor" href="#版本控制-10-个应用各自独立-git-仓库" aria-label="Permalink to “版本控制：10 个应用各自独立 git 仓库”">​</a></h2><p>每个应用都是<strong>独立的 git 仓库</strong>（不是一个大仓库里的子目录），提交历史按模块分批，面试时可直接 <code>git log</code> 看推进过程：</p><table tabindex="0"><thead><tr><th>约定</th><th>说明</th></tr></thead><tbody><tr><td>提交前缀</td><td><code>feat</code> / <code>test</code> / <code>docs</code> / <code>chore</code> + 圆括号标注系统名（如 <code>feat(erp): ...</code>）</td></tr><tr><td>分批粒度</td><td>基线快照 → 后端实现 → 测试脚本 → 前端 → 设计文档，每层一次提交</td></tr><tr><td>换行策略</td><td>统一 <code>.gitattributes</code>（<code>* text=auto eol=lf</code>），任何平台检出结果一致</td></tr><tr><td>不入库的内容</td><td><code>target/</code> / <code>node_modules/</code> / <code>dist/</code> 构建产物、数据库导出快照、商业授权 jar</td></tr></tbody></table><p><strong>为什么强调这一点</strong>：作品集的可信度不来自代码量，而来自「能验证的演进过程」。一把梭的 <code>initial commit</code> 证明不了任何东西，分层的 <code>feat → test → docs</code> 才能说明「先设计、再实现、再验证」。</p><h2 id="前端-模板化-元数据驱动" tabindex="-1">前端：模板化 + 元数据驱动 <a class="header-anchor" href="#前端-模板化-元数据驱动" aria-label="Permalink to “前端：模板化 + 元数据驱动”">​</a></h2><p>10 个前端均由统一模板 <code>E:/8.cangku/openbiz-app-template</code> 复制生成，复制后<strong>只需改 3 处</strong>：<code>src/config/modules.ts</code>（本系统元数据）、<code>vite.config.ts</code> 的 <code>BACKEND_PORT</code>、<code>index.html</code> 标题。</p><ul><li>技术栈：Vite 8 + Vue 3.5 + TypeScript 5.9 + Element Plus 2.14 + Vue Router 5 + Pinia 4 + axios 1.20</li><li>元数据驱动：菜单 / 路由 / 表格列 / 表单 / 状态流转 / 统计卡片全部由 <code>modules.ts</code> 生成</li><li>契约统一：<code>/login</code> 拿 token → <code>Authorization: Bearer</code>；实体 REST 为 <code>/api/{module}/{entity}</code> 的 <code>list / {id} / POST / PUT / DELETE / {id}/transition?to= / stats</code></li></ul><p><strong>标准契约兼容层</strong>：每个后端都新增 <code>StandardApiController</code>，把域特定端点（<code>/activate</code>、<code>/submit</code> 等）补齐为统一契约（<code>transition?to=</code> 状态机映射、<code>stats</code> 计数、<code>PUT</code>/<code>DELETE</code>）。错误由 <code>ApiExceptionHandler</code> 全局统一处理：非法流转返回 <strong>HTTP 409</strong> <code>{code:500,msg:&quot;ILLEGAL_TRANSITION&quot;}</code>，记录不存在返回 HTTP 400，控制器不再各自 try/catch。前端零特判，10 个应用一套前端代码模式。</p><blockquote><p>分页实现有代际差异：ERP 与 WMS 已把 <code>list</code> 下沉到 SQL（<code>COUNT</code> + <code>LIMIT/OFFSET</code>），其余应用仍是内存切片。差异如实标注，不做统一话术。</p></blockquote><h2 id="运行方式-以-crm-为例" tabindex="-1">运行方式（以 CRM 为例） <a class="header-anchor" href="#运行方式-以-crm-为例" aria-label="Permalink to “运行方式（以 CRM 为例）”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1) 后端（另开终端）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> E:/8.cangku/for-job/openbiz-crm-app/backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/openbiz-crm-app.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server.port=18084</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2) 前端（另开终端，自动代理到 18084）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> E:/8.cangku/for-job/openbiz-crm-app/frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 首次</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://localhost:5184</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>登录：<code>admin / admin123</code>（各应用独立库，账号互不影响）。</p><p><strong>已实测联调</strong>：CRM 应用经 Vite 代理完整链路 <strong>8/8 通过</strong>（登录→列表→新增→NEW→ACTIVE 流转→非法流转被拒(409)→不存在记录(400)→统计→商机列表）。</p><h2 id="复用模式-百套流水线脚手架" tabindex="-1">复用模式（百套流水线脚手架） <a class="header-anchor" href="#复用模式-百套流水线脚手架" aria-label="Permalink to “复用模式（百套流水线脚手架）”">​</a></h2><p>第 N 个应用的诞生只需四步：</p><ol><li><strong>建库</strong>：跑 <code>E:/8.cangku/split-databases.sh</code> 同款脚本（RuoYi 系统表 + 平台基础表 + 业务表）</li><li><strong>后端</strong>：复制任一 app 的 <code>backend/</code>，改数据源库名与端口，替换业务四层（domain/mapper/service/web）</li><li><strong>前端</strong>：复制 <code>openbiz-app-template</code>，改 <code>modules.ts</code> 元数据 + <code>BACKEND_PORT</code></li><li><strong>验证</strong>：跑统一契约 E2E（<code>backend/run_standard_e2e.sh</code>）</li></ol><p>完整脚手架与坑位清单见 <a href="/my-vitepress-site/apps/openbiz/scaffold.html">脚手架与坑位</a>。</p><h2 id="与「应用实例」页面的关系" tabindex="-1">与「应用实例」页面的关系 <a class="header-anchor" href="#与「应用实例」页面的关系" aria-label="Permalink to “与「应用实例」页面的关系”">​</a></h2><p>站点的<a href="/my-vitepress-site/instances/">应用实例</a>板块按<strong>场景</strong>组织（AI / 工业 / 企业 / 办公 / 工具），本板块按<strong>工程形态</strong>组织。两者交叉引用，同一套代码在两处都有落点：</p><table tabindex="0"><thead><tr><th>场景</th><th>对应 OpenBiz 应用</th></tr></thead><tbody><tr><td>工业数字化</td><td><a href="/my-vitepress-site/instances/industrial/mes.html">MES</a> · <a href="/my-vitepress-site/instances/industrial/wms.html">WMS</a> · <a href="/my-vitepress-site/instances/industrial/iiot.html">IIoT</a></td></tr><tr><td>企业业务</td><td><a href="/my-vitepress-site/instances/business/crm.html">CRM</a> · <a href="/my-vitepress-site/instances/business/erp.html">ERP</a> · <a href="/my-vitepress-site/instances/business/pms.html">PMS</a></td></tr><tr><td>办公自动化</td><td><a href="/my-vitepress-site/instances/office/oa.html">OA</a> · <a href="/my-vitepress-site/instances/office/bpm.html">BPM</a> · <a href="/my-vitepress-site/instances/office/hrm.html">HRM</a></td></tr><tr><td>智能制造</td><td><a href="/my-vitepress-site/apps/openbiz/workorder.html">工单</a>（生产协同）</td></tr></tbody></table><p>另有 3 个 AI 系统走独立套件（ModelDesk / langchain4j-lab / agent-demo），3 个个人工具不进 OpenBiz。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/">功能开发</a></p>`,38)])])}const m=e(i,[["render",n]]);export{b as __pageData,m as default};
